		zammad_access_token: {type: ''string''},
		zammad_group: {type: ''string''},
		zammad_enable_tags: {type: ''boolean'', default: false},
		event_nseverity: {type: ''integer'', default: -1},
		zabbix_url: {type: ''string'', url: true}
