INSERT INTO cep_rule (cep_ruleid,name,description,evaltype,formula,status,stop,sortorder) VALUES ('1','Close problems older than 2 weeks','Close events which are older than 14 days for data-center ''North''','0','','1','1','1'),
('2','Deduplicate repeating events by keeping only the cause problem','Reduce weekly problem noise by discarding repetitive events and increase counter ''repetition count'' for the cause event.','0','','1','1','1'),
('3','Detect physical security incident based on event pattern match','Rise a problem with name ''Engine issue'' when there are 3 engine start events.  Time between events is less than 7 seconds.','0','','1','1','1'),
('4','Detect missing ''communication'' events','Rise a problem "Risk detected: Communication down" when there is no events for 5 minutes for selected event conditions','0','','1','1','1'),
('5','Increase event severity and normalize tags','Increase event severity for ''Payments'' events and add tag ''env:prod'' if this tag does not exist','0','','1','1','1'),
('6','Reduce problem noise by grouping events','Reduce problem noise by keeping only one problem per host. After 3 days close all symptoms and increase cause severity.','1','','1','1','1');
