INSERT INTO cep_rule_window (cep_ruleid,type,duration,capacity,script,group_by_host_group,group_by_host,group_by_tags,tags,event_count_tag) VALUES ('1','1','14d','0','','0','0','0','',''),
('2','2','1w','0','','0','0','0','','repetition count'),
('3','4','1m','0','var events = cep_get_events().filter(function (e) {
    return e.name.indexOf(''engine start'') !== -1;
});

if (events.length < 3) {
    return false;
}

events.sort(function (a, b) { return a.clock - b.clock; });

for (var i = 1; i < events.length; i++) {
    if (events[i].clock - events[i - 1].clock >= 7) {
        return false;
    }
}

return true;','0','0','0','',''),
('4','4','1h','0','var events = cep_get_events();

if (events.length < 2) {
    return false;
}

events.sort(function (a, b) { return a.clock - b.clock; });

for (var i = 1; i < events.length; i++) {
    if (events[i].clock - events[i - 1].clock >= 300) {
        return true;
    }
}

return false;','0','0','0','',''),
('6','2','3d','0','','0','1','0','','');
