('39743','21','','10503','Get data','velocloud.get','{$VELOCLOUD.SDWAN.FREQUENCY}','0','0','0','4','','','','',NULL,NULL,E'const CTlsConfig = function (raw_value) {
	raw_value = String(raw_value).trim().toLowerCase();

	if ([''none'', ''peer'', ''full''].indexOf(raw_value) === -1) {
		raw_value = ''full'';
	}

	this.options = {
