('47069','21','','10627','Get ELB NLB alarms data','aws.elb.nlb.get_alarms','0s;m/1','0','0','0','4','','','','',NULL,NULL,E'const CTlsConfig = function (raw_value) {
	raw_value = String(raw_value).trim().toLowerCase();

	if ([''none'', ''peer'', ''full''].indexOf(raw_value) === -1) {
		raw_value = ''full'';
	}

	this.options = {
