function formatPSU(psuObj) {
	var foundPowerSupplies = [],
		buffer = [];

	psuObj.forEach(function (obj) {
		const psuName = obj[''name''].split('' '')[0];

		if (foundPowerSupplies.indexOf(psuName) === -1) {
