('61214','21','','10535','ECS clusters discovery','aws.ecs.discovery','12h','31d','365d','0','4','','','','',NULL,NULL,E'const CTlsConfig = function (raw_value) {
	raw_value = String(raw_value).trim().toLowerCase();

	if ([''none'', ''peer'', ''full''].indexOf(raw_value) === -1) {
		raw_value = ''full'';
	}

	this.options = {
		SSLVerifyPeer: (raw_value === ''peer'' || raw_value === ''full''),
		SSLVerifyHost: (raw_value === ''full'')
	};

	this.enabled = (raw_value !== ''none'');

	this.checkURL = function (url) {
		if (this.enabled && !/^https:\\/\\//i.test(url)) {
			throw ''TLS certificate verification is enabled by {$'' + ''HTTP.TLS.VERIFY}, but the URL uses plain HTTP: '' + url +
			''. Use an "https://" URL, or set {$'' + ''HTTP.TLS.VERIFY} to `none` to disable verification.'';
		}

		return url;
	};
}


var AWS = {
	params: {},
	metadata: ''http://169.254.169.254/latest/'',

	getRoleBaseCredentials: function () {
		AWS.params[''auth_type''] = ''role_base'';
		var request = new HttpRequest({SSLVerifyPeer: false, SSLVerifyHost: false});
		if (typeof AWS.params.proxy !== ''undefined'' && AWS.params.proxy !== '''') {
			request.setProxy(AWS.params.proxy);
		}
		request.addHeader(''X-aws-ec2-metadata-token-ttl-seconds: 21600'');
		var token = request.put(AWS.metadata + ''api/token'');

		if (request.getStatus() !== 200 || token === null || token === '''') {
			throw ''Error getting IMDSv2 session token.'';
		}
		request.addHeader(''X-aws-ec2-metadata-token: '' + token);
		var IamRoleName = request.get(AWS.metadata + ''meta-data/iam/security-credentials'');

		if (request.getStatus() !== 200 || IamRoleName === null || IamRoleName === '''') {
