('70574','11','','10589','Health: Get data','db.odbc.select[pgsql.health.snapshot.get,,"Database={$PG.DATABASE};{$PG.CONNSTRING.ODBC}"]','1m','0','0','0','4','','','','',NULL,NULL,'SELECT
  json_build_object (
    ''total_connections'',
    (
      SELECT
        count(*)
      FROM
        pg_stat_activity
    ),
    ''active_connections'',
    (
      SELECT
        count(*)
      FROM
        pg_stat_activity
      WHERE
        state = ''active''
    ),
    ''waiting_locks'',
    (
      SELECT
        count(*)
      FROM
        pg_locks
      WHERE
        NOT granted
    ),
    ''max_xid_age'',
    (
      SELECT
        max(age (datfrozenxid))
      FROM
        pg_database
    ),
    ''max_xid_percent'',
    (
      SELECT
        round(100.0 * max(age (datfrozenxid)) / 2000000000, 6)
      FROM
        pg_database
    ),
    ''cache_hit_ratio'',
    (
      SELECT
        round(
          100.0 * sum(blks_hit) / nullif(sum(blks_hit + blks_read), 0),
          2
        )
      FROM
        pg_stat_database
    ),
    ''deadlocks'',
    (
      SELECT
        sum(deadlocks)
      FROM
        pg_stat_database
    ),
    ''autovacuum'',
    json_build_object (
      ''active'',
      (
        SELECT
          count(*)
        FROM
          pg_stat_activity
        WHERE
          backend_type = ''autovacuum worker''
          AND state <> ''idle''
      ),
      ''idle'',
      (
        SELECT
          count(*)
        FROM
          pg_stat_activity
        WHERE
          backend_type = ''autovacuum worker''
          AND state = ''idle''
      )
    )
  ) AS health;','','0','{$PG.USER}','{$PG.PASSWORD}','','','0',NULL,'Collects raw PostgreSQL health metrics.','0','7d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','e5df321a28e043b292abdc5061ffb480','0','2','0','{}','15s','10m','15s','0'),
('70575','11','','10589','LRQ: Get data','db.odbc.select[pgsql.longest.running.query.data.get,,"Database={$PG.DATABASE};{$PG.CONNSTRING.ODBC}"]','1m','0','0','0','4','','','','',NULL,NULL,'SELECT
  json_build_object (
    ''pid'',
    pid,
    ''duration'',
    EXTRACT(
      EPOCH
      FROM
        now () - query_start
    ),
    ''query'',
    query
  ) AS result
FROM
  pg_stat_activity
WHERE
  state = ''active''
  AND query NOT LIKE ''START_REPLICATION SLOT%''
ORDER BY
