LIMIT
  1;','','0','{$PG.USER}','{$PG.PASSWORD}','','','0',NULL,'Returns data about the currently active LRQ (Longest Running Query) and its execution duration from `pg_stat_activity`.','0','7d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','e1f5776255024fc49507a4ed15e7fc16','0','2','0','{}','15s','10m','15s','0'),
('70576','11','','10589','Get relation inventory','db.odbc.select[pgsql.relation.inventory.get,,"Database={$PG.DATABASE};{$PG.CONNSTRING.ODBC}"]','1m','0','0','0','4','','','','',NULL,NULL,'SELECT
    json_object_agg (
        schema_name,
        json_build_object (
            ''total_bytes'',
            total_bytes,
            ''table_count'',
            table_count
        )
    )
FROM
    (
        SELECT
            n.nspname AS schema_name,
            COALESCE(SUM(pg_total_relation_size (c.oid)), 0) AS total_bytes,
            COUNT(c.oid) AS table_count
        FROM
            pg_namespace n
            LEFT JOIN pg_class c ON c.relnamespace = n.oid
            AND c.relkind = ''r''
        WHERE
            n.nspname NOT IN (''pg_catalog'', ''information_schema'')
        GROUP BY
            n.nspname
    ) AS sub;','','0','{$PG.USER}','{$PG.PASSWORD}','','','0',NULL,'Collects raw relation size information from the primary core database.','0','7d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','fefca23f666f46fdb870340913589dc5','0','2','0','{}','15s','10m','15s','0'),
