('70623','11','','10589','WAL statistics: Get data','db.odbc.select[pgsql.wal.stats.above.14.get{#SINGLETON},,"Database={$PG.DATABASE};{$PG.CONNSTRING.ODBC}"]','1m','0','0','0','4','','','','',NULL,NULL,'WITH
  wal AS (
    SELECT
      wal_records,
      wal_fpi,
      wal_bytes,
      wal_buffers_full,
      stats_reset
    FROM
      pg_stat_wal
  ),
  rep AS (
    SELECT
      json_agg (
        json_build_object (
          ''pid'',
          pid,
          ''application_name'',
          application_name,
          ''client_addr'',
          client_addr,
          ''state'',
          state,
          ''sent_lsn'',
          sent_lsn,
          ''write_lsn'',
          write_lsn,
          ''flush_lsn'',
          flush_lsn,
          ''replay_lsn'',
          replay_lsn,
          ''write_lag'',
          write_lag,
          ''flush_lag'',
          flush_lag,
          ''replay_lag'',
          replay_lag,
          ''sync_state'',
          sync_state
        )
      ) AS replication
    FROM
      pg_stat_replication
  ),
  receiver AS (
    SELECT
      json_build_object (
        ''pid'',
        pid,
        ''status'',
        status,
        ''written_lsn'',
        written_lsn,
        ''flushed_lsn'',
        flushed_lsn,
        ''received_tli'',
        received_tli,
        ''last_msg_send_time'',
        last_msg_send_time,
        ''last_msg_receipt_time'',
        last_msg_receipt_time,
        ''latest_end_lsn'',
        latest_end_lsn,
        ''latest_end_time'',
        latest_end_time
      ) AS receiver
    FROM
      pg_stat_wal_receiver
  ),
  slots AS (
    SELECT
      json_agg (
        json_build_object (
          ''slot_name'',
          slot_name,
          ''plugin'',
          plugin,
          ''slot_type'',
          slot_type,
          ''database'',
          database,
          ''active'',
          active,
          ''restart_lsn'',
          restart_lsn,
          ''confirmed_flush_lsn'',
          confirmed_flush_lsn,
          ''wal_status'',
          wal_status,
          ''safe_wal_size'',
          safe_wal_size
        )
      ) AS slots
    FROM
      pg_replication_slots
  )
SELECT
  json_build_object (
    ''wal'',
    (
      SELECT
        row_to_json (wal)
      FROM
        wal
    ),
    ''replication'',
    (
      SELECT
        replication
      FROM
        rep
    ),
    ''receiver'',
    (
      SELECT
        receiver
      FROM
        receiver
    ),
    ''slots'',
    (
      SELECT
        slots
      FROM
        slots
    )
  ) AS result;','','0','{$PG.USER}','{$PG.PASSWORD}','','','2',NULL,'Collects WAL activity metrics from `pg_stat_wal`.','0','7d','0','',NULL,'','','','','200','1','0','','','0','0','0','0','0','0','0','9aa6e88e063a4beba6f373be04ea4f4a','0','2','0','{}','15s','10m','15s','0'),
('70624','11','','10589','Workload: Get data','db.odbc.select[pgsql.workload.snapshot.above.15.get{#SINGLETON},,"Database={$PG.DATABASE};{$PG.CONNSTRING.ODBC}"]','1m','0','0','0','4','','','','',NULL,NULL,'WITH
