('70629','11','','10589','Workload: Get data','db.odbc.select[pgsql.workload.snapshot.version.18.get{#SINGLETON},,"Database={$PG.DATABASE};{$PG.CONNSTRING.ODBC}"]','1m','0','0','0','4','','','','',NULL,NULL,'WITH pgss_config AS (
    SELECT
