				}
			});
		}

		for (var i = months_back - 1; i >= 0; i--) {
			var month_start = new Date(Date.UTC(
				current_month.getUTCFullYear(),
				current_month.getUTCMonth() - i,
				1
			));

			var month = month_start.toISOString().substring(0, 7);

			monthly_cost_array.push({
				month: month,
				cost: monthly_costs[month] ? Number(monthly_costs[month].cost) : 0,
				currency: monthly_costs[month] ? monthly_costs[month].currency : ''''
			});
		}

		result.usage[result_key] = monthly_cost_array;
	}
	catch (error) {
		result.errors.push(error_label + '': '' + error);

