('29130','{42507}<{$PROXY.GROUP.AVAIL.PERCENT.MIN}','Zabbix server: Proxy group [{#PROXY.GROUP.NAME}]: Availability too low','','0','2','The availability of proxies in a proxy group is below {$PROXY.GROUP.AVAIL.PERCENT.MIN}% for at least 3 minutes.','29109','0','2','0','','0','','0','Current value: {ITEM.LASTVALUE1}','0','Zabbix server: Proxy group [{#PROXY.GROUP.NAME}]: Availability below {$PROXY.GROUP.AVAIL.PERCENT.MIN}%','',''),
