('135394','70790','2','21','var HuaweiNqaParser = {

	decodeAscii: function(parts, start, length) {
		var chars = [],
			j;

		for (j = 0; j < length; j++) {
			chars.push(String.fromCharCode(+parts[start + j]));
		}

		return chars.join('''');
	},

	parse: function(data) {
		var grouped = {},
			i,
			row,
			parts,
			admin_len,
			admin_start,
			admin,
			test_len,
			test_start,
			test,
			probe_pos,
			probe,
			key;

		for (i = 0; i < data.length; i++) {
			row = data[i];

			if (typeof row[''{#SNMPINDEX}''] === ''undefined'') {
				continue;
			}

			parts = row[''{#SNMPINDEX}''].split(''.'');

			admin_len = +parts[0];
			admin_start = 1;

			admin = this.decodeAscii(parts, admin_start, admin_len);

			test_len = +parts[admin_start + admin_len];
			test_start = admin_start + admin_len + 1;

			test = this.decodeAscii(parts, test_start, test_len);

			probe_pos = test_start + test_len;
			probe = +parts[probe_pos];

			key = admin + ''|'' + test;

			if (typeof grouped[key] === ''undefined'' || probe > grouped[key].probe) {
				grouped[key] = {
					admin: admin,
					test: test,
					probe: probe,
					rttAvg: Number(row.rttAvg),
					rttMax: Number(row.rttMax),
					rttMin: Number(row.rttMin),
					packetLoss: Number(row.packetLoss),
					jitter: Number(row.jitter)
				};
			}
		}

		return grouped;
	}
};

