			}
			if (m.billing_month === prev_month) {
				total_prev_month = m.total_cost;
			}
		});

		if (total_current_month === ''0'' && monthly_costs.length > 0) {
			var last = monthly_costs[monthly_costs.length - 1];
			total_current_month = last.total_cost;
			currency_current = last.currency;
		}

		var prev_num = parseFloat(total_prev_month),
			monthly_change_pct = prev_num > 0
				? parseFloat(((parseFloat(total_current_month) - prev_num) / prev_num * 100).toFixed(2))
				: null,
			result = {
