			};

		if (monthly_change_pct !== null) {
			result.monthly_change_pct = monthly_change_pct;
		}

		result.billing_summary = [
			{metric: ''current_month'', label: ''Current month'', total_cost: total_current_month, currency: currency_current}
		];
		if (total_prev_month !== ''0'') {
			result.billing_summary.push({metric: ''prev_month'', label: ''Previous month'', total_cost: total_prev_month, currency: currency_current});
		}

		return result;
	}
};

